import json
from collections import defaultdict

def get_regions(grid):
    """Get disjoint connected regions for each color"""
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    regions_by_color = defaultdict(list)

    for r in range(rows):
        for c in range(cols):
            color = grid[r][c]
            if visited[r][c]:
                continue

            # BFS to find region
            region = []
            queue = [(r, c)]
            visited[r][c] = True
            while queue:
                position = queue.pop(0)
                region.append(position)
                rr, cc = position
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = rr + dr, cc + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if not visited[nr][nc] and grid[nr][nc] == color:
                            visited[nr][nc] = True
                            queue.append((nr, nc))
            regions_by_color[color].append(region)

    # Calculate bbox for each region
    result = {}
    for color, regions in regions_by_color.items():
        result[color] = {}
        for i, region in enumerate(regions):
            rmin, cmin = min(r for r, c in region), min(c for r, c in region)
            rmax, cmax = max(r for r, c in region), max(c for r, c in region)
            result[color][i] = {
                'bbox': (rmin, cmin, rmax, cmax),
                'pixels': len(region)
            }
    return result

