import json
from collections import defaultdict

def transform(grid):
    """Transformation: fill bounding boxes of multi-pixel non-background regions"""
    rows, cols = len(grid), len(grid[0])

    # Find background color (most frequent)
    counter = defaultdict(int)
    for row in grid:
        for val in row:
            counter[val] += 1
    background = max(counter.keys(), key=lambda c: counter[c])

    # Find connected regions with size >= 2 for each non-background color
    visited = [[False]*cols for _ in range(rows)]
    filled_regions = []  # List of (color, rmin, rmax, cmin, cmax)

    for r in range(rows):
        for c in range(cols):
            color = grid[r][c]
            if color != background and not visited[r][c]:
                # Find region
                region = []
                queue = [(r, c)]
                visited[r][c] = True
                while queue:
                    pos = queue.pop(0)
                    region.append(pos)
                    rr, cc = pos
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = rr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and grid[nr][nc] == color:
                            visited[nr][nc] = True
                            queue.append((nr, nc))

                # Keep only if region has >= 2 pixels (multi-pixel)
                if len(region) >= 2:
                    rmin, rmax = min(p[0] for p in region), max(p[0] for p in region)
                    cmin, cmax = min(p[1] for p in region), max(p[1] for p in region)
                    filled_regions.append((color, rmin, rmax, cmin, cmax))

    # Start with background-filled grid
    output = [[background] * cols for _ in range(rows)]

    # Fill each region's bbox
    for color, rmin, rmax, cmin, cmax in filled_regions:
        for r in range(rmin, rmax + 1):
            for c in range(cmin, cmax + 1):
                output[r][c] = color

    return output

# Test on demo
